INSERT INTO countries (name, code, official_name, legal_family, government_system, legal_system_note, requires_region, group_key) VALUES
('Türkiye','TR','Türkiye Cumhuriyeti','Kıta Avrupası / kanun temelli','Cumhuriyet / başkanlık tipi yürütme','Yargı yetkisi bağımsız ve tarafsız mahkemelerce kullanılır; anayasal haklar ve kanunilik ilkesi önemlidir.',0,'TR'),
('Amerika Birleşik Devletleri','US','United States of America','Common law + federal yapı','Federal cumhuriyet / başkanlık','Ceza hukuku federal ve eyalet düzeyinde farklılaşabilir. Eyalet/bölge seçimi zorunlu kabul edilmelidir.',1,'US'),
('Almanya','DE','Federal Republic of Germany','Kıta Avrupası / federal yapı','Federal cumhuriyet / parlamenter','Ceza hukuku büyük ölçüde federal kanunlara dayanır; eyalet yapısı idari süreçte etkili olabilir.',0,'EU'),
('Fransa','FR','French Republic','Kıta Avrupası / kodifiye hukuk','Cumhuriyet / yarı başkanlık','Yazılı kanunlar, savcılık soruşturması ve mahkeme aşamaları belirleyicidir.',0,'EU'),
('İngiltere ve Galler','GB-EW','England and Wales','Common law','Anayasal monarşi / parlamenter','Emsal kararlar, statute law ve savcılık değerlendirmesi birlikte önemlidir. İskoçya/Kuzey İrlanda farklıdır.',1,'UK'),
('Avusturya','AT','Republic of Austria','Kıta Avrupası / federal yapı','Cumhuriyet / parlamenter','Federal anayasal düzen vardır; ceza hukuku kanunilik ve kusur ilkeleriyle değerlendirilir.',0,'EU'),
('Belçika','BE','Kingdom of Belgium','Kıta Avrupası / federal yapı','Anayasal monarşi / parlamenter','Federal devlet yapısı ve dil toplulukları önemlidir; ceza değerlendirmesi kanuna bağlıdır.',0,'EU'),
('Brezilya','BR','Federative Republic of Brazil','Kıta Avrupası etkili / federal yapı','Federal cumhuriyet / başkanlık','Federal yapı vardır; ceza kanunu ve eyalet uygulamaları birlikte görülebilir.',1,'LATAM'),
('Bulgaristan','BG','Republic of Bulgaria','Kıta Avrupası','Cumhuriyet / parlamenter','Yazılı anayasa ve ceza kanunu temellidir; savcılık-yargı süreci belirleyicidir.',0,'EU'),
('Çek Cumhuriyeti','CZ','Czech Republic','Kıta Avrupası','Cumhuriyet / parlamenter','Temel haklar bildirgesi anayasal sistemin parçasıdır; kanunilik ilkesi önemlidir.',0,'EU'),
('Danimarka','DK','Kingdom of Denmark','Nordik hukuk / anayasal monarşi','Anayasal monarşi / parlamenter','Ceza hukuku kanun ve mahkeme uygulamalarıyla şekillenir; süreç savcılık üzerinden ilerler.',0,'NORDIC'),
('Estonya','EE','Republic of Estonia','Kıta Avrupası / dijital devlet güçlü','Cumhuriyet / parlamenter','Dijital haklar ve kişisel veriler pratikte önemlidir; ceza hukuku kanun temellidir.',0,'EU'),
('Finlandiya','FI','Republic of Finland','Nordik hukuk','Cumhuriyet / parlamenter','Temel haklar ve ölçülülük yaklaşımı güçlüdür; ceza süreci savcılık ve mahkeme eksenindedir.',0,'NORDIC'),
('Güney Afrika','ZA','Republic of South Africa','Karma hukuk','Cumhuriyet / parlamenter ağırlıklı','Anayasal haklar kataloğu güçlüdür; ceza yargılamasında adil yargılanma ve delil önemlidir.',0,'COMMON'),
('Güney Kore','KR','Republic of Korea','Kıta Avrupası etkili karma sistem','Cumhuriyet / başkanlık','Ceza kanunu, savcılık soruşturması ve mahkeme kararı belirleyicidir.',0,'ASIA'),
('Hollanda','NL','Kingdom of the Netherlands','Kıta Avrupası','Anayasal monarşi / parlamenter','Kanun temelli ceza düzeni ve savcılık takdiri önemlidir.',0,'EU'),
('İrlanda','IE','Ireland','Common law','Cumhuriyet / parlamenter','Common law etkisi ve yazılı kanunlar birlikte rol oynar; savcılık değerlendirmesi önemlidir.',0,'COMMON'),
('İspanya','ES','Kingdom of Spain','Kıta Avrupası / özerk bölgeler','Anayasal monarşi / parlamenter','Özerk bölgeler idari açıdan etkili olabilir; ceza hukuku temel olarak ulusal kanunlara dayanır.',1,'EU'),
('İtalya','IT','Italian Republic','Kıta Avrupası','Cumhuriyet / parlamenter','Ceza kanunu, savcılık ve mahkeme süreci belirleyicidir; kanunilik ilkesi güçlüdür.',0,'EU'),
('Macaristan','HU','Hungary','Kıta Avrupası','Cumhuriyet / parlamenter','Temel yasa ve ceza kanunu kapsamında değerlendirme yapılır.',0,'EU'),
('Polonya','PL','Republic of Poland','Kıta Avrupası','Cumhuriyet / parlamenter','Ceza kanunu ve anayasal haklar çerçevesinde soruşturma-kovuşturma süreci işler.',0,'EU'),
('Portekiz','PT','Portuguese Republic','Kıta Avrupası','Cumhuriyet / yarı başkanlık','Ceza hukuku kanunilik, kusur ve ölçülülük ilkeleriyle değerlendirilir.',0,'EU'),
('Romanya','RO','Romania','Kıta Avrupası','Cumhuriyet / yarı başkanlık','Ceza kanunu ve savcılık sistemi belirleyicidir.',0,'EU'),
('Rusya','RU','Russian Federation','Kıta Avrupası etkili / federal yapı','Federal cumhuriyet / başkanlık','Federal yapı vardır; ceza kanunu ve devlet organlarının yetkileri önemlidir.',1,'EURASIA'),
('Yunanistan','GR','Hellenic Republic','Kıta Avrupası','Cumhuriyet / parlamenter','Ceza hukuku kanun temellidir; savcılık ve mahkeme süreci önemlidir.',0,'EU');
