INSERT INTO legal_contents (country_id, crime_type_id, law_article, possible_penalty, process_note, rights_note, judge_simulation_note, source_note, is_seed_data) VALUES
((SELECT id FROM countries WHERE code='TR'),(SELECT id FROM crime_types WHERE slug='hirsizlik'),'TCK m.141-142: Hırsızlık ve nitelikli hırsızlık hükümleri; eşyanın değeri, yer, zaman, kilit/kamu kurumu gibi nitelikli haller sonucu etkiler.','Kesin ceza söylenemez. Kanundaki yaptırım; suçun temel/nitelikli hali, zarar, kast/taksir, yaş, ilk suç, pişmanlık, uzlaşma, mağdurun durumu, delil ve yerel kanuna göre değişir.','Genel süreç: olay bildirimi/şikâyet veya kolluk tespiti → ifade ve delil toplama → savcılık değerlendirmesi → dava açılması, uzlaşma/alternatif çözüm, takipsizlik veya mahkeme kararı ihtimali. Ülkeye göre süreler ve makam isimleri değişebilir.','Avukata danışma, susma/ifade vermeme hakları konusunda bilgi alma, tercüman isteme, delilleri saklama, resmi çağrı ve evrakları ihmal etmeme, yanlış beyandan kaçınma önemlidir.','Suçun kanuni unsurları, kast/taksir, zarar, mağdur rızası, delil yeterliliği, hafifletici/ağırlaştırıcı nedenler ve ilk suç olup olmama birlikte değerlendirilir.','Türkiye için TCK madde başlıkları tohum veri olarak eklenmiştir; güncel mevzuat kontrol edilmelidir.',1),
((SELECT id FROM countries WHERE code='TR'),(SELECT id FROM crime_types WHERE slug='dolandiricilik'),'TCK m.157-158: Dolandırıcılık ve nitelikli dolandırıcılık; hileli davranış, aldatma kabiliyeti ve menfaat temini aranır.','Kesin ceza söylenemez. Kanundaki yaptırım; suçun temel/nitelikli hali, zarar, kast/taksir, yaş, ilk suç, pişmanlık, uzlaşma, mağdurun durumu, delil ve yerel kanuna göre değişir.','Genel süreç: olay bildirimi/şikâyet veya kolluk tespiti → ifade ve delil toplama → savcılık değerlendirmesi → dava açılması, uzlaşma/alternatif çözüm, takipsizlik veya mahkeme kararı ihtimali. Ülkeye göre süreler ve makam isimleri değişebilir.','Avukata danışma, susma/ifade vermeme hakları konusunda bilgi alma, tercüman isteme, delilleri saklama, resmi çağrı ve evrakları ihmal etmeme, yanlış beyandan kaçınma önemlidir.','Suçun kanuni unsurları, kast/taksir, zarar, mağdur rızası, delil yeterliliği, hafifletici/ağırlaştırıcı nedenler ve ilk suç olup olmama birlikte değerlendirilir.','Türkiye için TCK madde başlıkları tohum veri olarak eklenmiştir; güncel mevzuat kontrol edilmelidir.',1),
((SELECT id FROM countries WHERE code='TR'),(SELECT id FROM crime_types WHERE slug='hakaret'),'TCK m.125: Hakaret; mağdurun onur, şeref ve saygınlığını hedefleyen söz/fiil/iletiler değerlendirilir.','Kesin ceza söylenemez. Kanundaki yaptırım; suçun temel/nitelikli hali, zarar, kast/taksir, yaş, ilk suç, pişmanlık, uzlaşma, mağdurun durumu, delil ve yerel kanuna göre değişir.','Genel süreç: olay bildirimi/şikâyet veya kolluk tespiti → ifade ve delil toplama → savcılık değerlendirmesi → dava açılması, uzlaşma/alternatif çözüm, takipsizlik veya mahkeme kararı ihtimali. Ülkeye göre süreler ve makam isimleri değişebilir.','Avukata danışma, susma/ifade vermeme hakları konusunda bilgi alma, tercüman isteme, delilleri saklama, resmi çağrı ve evrakları ihmal etmeme, yanlış beyandan kaçınma önemlidir.','Suçun kanuni unsurları, kast/taksir, zarar, mağdur rızası, delil yeterliliği, hafifletici/ağırlaştırıcı nedenler ve ilk suç olup olmama birlikte değerlendirilir.','Türkiye için TCK madde başlıkları tohum veri olarak eklenmiştir; güncel mevzuat kontrol edilmelidir.',1),
((SELECT id FROM countries WHERE code='TR'),(SELECT id FROM crime_types WHERE slug='tehdit'),'TCK m.106: Tehdit; hayat, vücut veya malvarlığına yönelik ciddi zarar bildirimi ve elverişlilik incelenir.','Kesin ceza söylenemez. Kanundaki yaptırım; suçun temel/nitelikli hali, zarar, kast/taksir, yaş, ilk suç, pişmanlık, uzlaşma, mağdurun durumu, delil ve yerel kanuna göre değişir.','Genel süreç: olay bildirimi/şikâyet veya kolluk tespiti → ifade ve delil toplama → savcılık değerlendirmesi → dava açılması, uzlaşma/alternatif çözüm, takipsizlik veya mahkeme kararı ihtimali. Ülkeye göre süreler ve makam isimleri değişebilir.','Avukata danışma, susma/ifade vermeme hakları konusunda bilgi alma, tercüman isteme, delilleri saklama, resmi çağrı ve evrakları ihmal etmeme, yanlış beyandan kaçınma önemlidir.','Suçun kanuni unsurları, kast/taksir, zarar, mağdur rızası, delil yeterliliği, hafifletici/ağırlaştırıcı nedenler ve ilk suç olup olmama birlikte değerlendirilir.','Türkiye için TCK madde başlıkları tohum veri olarak eklenmiştir; güncel mevzuat kontrol edilmelidir.',1),
