CREATE DATABASE IF NOT EXISTS cerise_legal_assistant CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cerise_legal_assistant;

SET NAMES utf8mb4;

DROP TABLE IF EXISTS case_analyses;
DROP TABLE IF EXISTS legal_contents;
DROP TABLE IF EXISTS legal_sources;
DROP TABLE IF EXISTS country_regions;
DROP TABLE IF EXISTS crime_types;
DROP TABLE IF EXISTS countries;


CREATE TABLE countries (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  code VARCHAR(16) NOT NULL UNIQUE,
  official_name VARCHAR(180) NULL,
  legal_family VARCHAR(120) NULL,
  government_system VARCHAR(160) NULL,
  legal_system_note TEXT,
  requires_region TINYINT(1) DEFAULT 0,
  group_key VARCHAR(40) NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE country_regions (
  id INT AUTO_INCREMENT PRIMARY KEY,
  country_id INT NOT NULL,
  name VARCHAR(160) NOT NULL,
  note TEXT NULL,
  FOREIGN KEY (country_id) REFERENCES countries(id) ON DELETE CASCADE,
  UNIQUE KEY uniq_country_region (country_id, name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE crime_types (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  slug VARCHAR(160) NOT NULL UNIQUE,
  keywords TEXT,
  default_questions TEXT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE legal_sources (
  id INT AUTO_INCREMENT PRIMARY KEY,
  country_id INT NULL,
  title VARCHAR(255) NOT NULL,
  source_type VARCHAR(80) DEFAULT 'reference',
  local_path VARCHAR(255) NULL,
  url VARCHAR(500) NULL,
  note TEXT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (country_id) REFERENCES countries(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE legal_contents (
  id INT AUTO_INCREMENT PRIMARY KEY,
  country_id INT NOT NULL,
  crime_type_id INT NOT NULL,
  law_article VARCHAR(700),
  possible_penalty TEXT,
  process_note TEXT,
  rights_note TEXT,
  judge_simulation_note TEXT,
  source_note TEXT NULL,
  is_seed_data TINYINT(1) DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (country_id) REFERENCES countries(id) ON DELETE CASCADE,
  FOREIGN KEY (crime_type_id) REFERENCES crime_types(id) ON DELETE CASCADE,
  UNIQUE KEY uniq_country_crime (country_id, crime_type_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE case_analyses (
  id INT AUTO_INCREMENT PRIMARY KEY,
  country_id INT NOT NULL,
  region VARCHAR(120) NULL,
  event_text TEXT NOT NULL,
  crime_type_id INT NULL,
  result_json JSON NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (country_id) REFERENCES countries(id) ON DELETE CASCADE,
  FOREIGN KEY (crime_type_id) REFERENCES crime_types(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;





ON DUPLICATE KEY UPDATE law_article=VALUES(law_article), possible_penalty=VALUES(possible_penalty), process_note=VALUES(process_note), rights_note=VALUES(rights_note), judge_simulation_note=VALUES(judge_simulation_note), source_note=VALUES(source_note);
